*******************************************************************			 ******          Memory	Manager Patch		 ******          For ROM 2.0		 ******          (C) Copyright Apple Computer, Inc. 1985-1989	 ******          All Rights Reserved		 ******			 ****** Version 1.0 in ROM		 ******			 ****** Version 1.1  (System Disk 1.0)		 ******    September 4,	1986		 ******    Rich Williams		 ******			 ******    1.  Adds automactic purging		 ******    2.  Fixes problem with ownership	of blocks of	 ******        handles.			 ******			 ****** Version 1.2  (System Disk 1.1)		 ******    November 14,	1986		 ******    Rich Williams		 ******			 ******    1.  Purging is more intelligent when a fixed	 ******        handle must be allocated in special memory	 ******			 ******			 ****** System Disk 2.0			 ******			 ******    No changes.			 ******			 ****** System Disk 2.1	(3.0)		 ******			 ******    No changes			 ******			 ****** System Disk 3.1			 ******			 ******    No changes			 ******			 ****** System Disk 3.1.1		 ******			 ******    Added call:	RealFreeMem ($2F)		 ******			 ******			 ****** System Disk 3.2 (Version 2.2)		 ******			 ******    Fixed bug in RealFreeMem		 ******			 ******    15 Jun 88	Harry Yee		 ******			 ******    Prototype bit taken out of version number.	 ******			 ********* System Disk 4.1 (Version 2.3)****** 01 Dec 88	Steven Glass****** Major reorganization of code.  We now share where*** ever possible with the ROM source.****** Added patches to system to speed up Searching.  These*** included patches to DisposeHandle, DisposeAll, PurgeHandle*** PurgeAll and SetHandleSize so that the fast stuff*** works.****** Changed purgeall to work with 0 ID.****** Changed DisposeAll to check calling routine to make*** sure that it did not dispose of itself.********* 08 Jan 89	Steven Glass****** Changed bootinit and reset to zero the FirstOOMPtr*** clearing the OOMQueue.****** 30 Mar 89	Steven Glass****** Added code to MMPatcher routine to restore the BellVector*** which was saved in the original install routine.****** 11/13/89	Mensch*** Fixed dispose handle to use the new verify routine to catch*** more bad handles****** 07 Aug 90	Yee*** Change to final version number for 5.0.3, v3.1.** 22-Jan-91	Dave Lyons** Add new call $3002 SetHandleID.  Changed MMVersion to $8302.** 12-Jun-91	Dave Lyons** Added check in DisposeHandle to disallow disposing the first handle.* This would be very bad.  Now returns error $0206.** 14-Sep-91	Dave Lyons** No change to this file, but fixed a bug in CheckRecent in* mm:mm.asm, which is linked into these patches.** 21-Nov-91	Dave Lyons** DisposeHandle on first handle now returns error 0 for* compatibility.** 31-Jan-92	Dave Lyons** Made NewMMPatcher disable interrupts and fix the ToBramSetup vector* ($e10094).** 5-Feb-92	Dave Lyons** Version $0302 for 6.0 final.*****************************************************************	title 'Memory Manager Patches'	include 'all.macros'MMVersionNum	equ $0302SHSReturn	equ $FF076A	INCLUDE ':::mm:mm.equates.asm'BellVector	equ DecBusyFlg+4	Title 'Call Table'*****************************************************************MMCallTable	PROC EXPORT** References to all calls that are patched.*** Inputs:*	none** Outputs:*	none** External Refs:	IMPORT MMBootInit	IMPORT MMVersion	IMPORT RealFreeMem	import MMReset	import AddToOOMQueue	import DeleteFromOOMQueue	import DisposeHandle	import DisposeAll	import PurgeHandle	import PurgeAll	import SetHandleSize	import MMShutdown	import SetHandleID	;22-Jan-91 DAL** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	DC.L (TableEnd-mmCallTable)/4 ; # entries + 1	DC.L MMBootInit-1	;01 Boot time call	DC.L 0	;               i4'MMStartup-1'        ;02 Application init	call	DC.L MMShutdown-1   ;03 App quit	DC.L MMVersion-1	;04 Version #	DC.L MMReset-1		;05 Reset call	DC.L 0	;               i4'MMStatus-1'         ;06 Active status	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'NewHandle-1'        ;09 NewHandle	DC.L 0	;               i4'ReallocHandle-1'    ;0A ReallocHandle	DC.L 0	;               i4'RestoreHandle-1'    ;0B RestoreHandle	DC.L AddToOOMQueue-1	DC.L DeleteFromOOMQueue-1	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'NotImp-1'	DC.L DisposeHandle-1		;10 DisposHandle	DC.L DisposeAll-1		;11 DisposAll	DC.L PurgeHandle-1		;12 PurgeHandle	DC.L PurgeAll-1		;13 PurgeAll	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'GetHandleSize-1'    ;18 GetHandleSize	DC.L SetHandleSize-1	; 19 SetHandleSize	DC.L 0	;               i4'FindHandle-1'       ;1A FindHandle	DC.L 0	;               i4'FreeMem-1'          ;1B FreeMem	DC.L 0	;               i4'MaxBlock-1'         ;1C MaxBlock	DC.L 0	;               i4'TotalMem-1'         ;1D TotalMem	DC.L 0	;               i4'CheckHandle-1'      ;1E CheckHandle	DC.L 0	;               i4'CompactMem-1'       ;1F CompactMem	DC.L 0	;               i4'HLock-1'            ;20 HLock	DC.L 0	;               i4'HLockAll-1'         ;21 HLockAll	DC.L 0	;               i4'HUnlock-1'          ;22 HUnlock	DC.L 0	;               i4'HUnlockAll-1'       ;23 HUnlockAll	DC.L 0	;               i4'SetPurge-1'         ;24 SetPurge	DC.L 0	;               i4'SetPurgeAll-1'      ;25 SetPurgeAll	DC.L 0	;               i4'NotImp-1'           ;26 DeRef	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'PtrToHand-1'        ;28 PtrToHand	DC.L 0	;               i4'HandToPtr-1'        ;29 HandToPtr	DC.L 0	;               i4'HandToHand-1'       ;2A HandToHand	DC.L 0	;               i4'BlockMove-1'        ;2B BlockMove	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'NotImp-1'	DC.L 0	;               i4'NotImp-1'	DC.L RealFreeMem-1	;2F RealFreeMem	dc.l SetHandleID-1	;30 SetHandleID 22-Jan-91 DALTableEnd		;	ENDP*****************************************************************MMBootInit	PROC** This is called when the patche is installed.  We patch* six memory manager vectors at this time.** These vectors are reset to their original state* by the routine MMPatcher (also a vector) so that the* patch does not try to run after the machine is * rebooted.*** Inputs:*	none** Outputs:*	none** External Refs:	import NewSearch	import OrigLink	import NewLink	import XUserPurge	import XSearchFail	import XPurge	import OrigBellVector** Entry Points:*	none*	longa on	; mode	longi on*** Change History** 08 Jan 89	Steven Glass** Also zeroed the FirstOOMPtr so that reboot clears the OOM* queue.*****************************************************************	import ClearRecent	phb	pea $E1E1	plb	plb	jsr ClearRecent;; Clear the OOM queue.;	stz |FirstOOMPtr	stz |FirstOOMPtr+2	lda |Search+1	cmp #NewSearch	bne @Continue	brl DoNothing@Continue; Save the search vector	lda |Search	sta >OrigSearch	lda |Search+2	sta >OrigSearch+2; Set the new search vector	lda #NewSearch	sta |Search+1	lda #>NewSearch	sta |Search+2; Set the MMPatcher vector	lda |MMPatcher	sta >OrigMMPatcher	lda |MMPatcher+2	sta >OrigMMPatcher+2; Set the new MMPatcher vector	lda #NewMMPatcher	sta |MMPatcher+1	lda #>NewMMPatcher	sta |MMPatcher+2; Save the Link vector	lda |Link	sta >OrigLink	lda |Link+2	sta >OrigLink+2; Set the new Link vector	lda #NewLink	sta |Link+1	lda #>NewLink	sta |Link+2; Save the UserPurge vector	lda |UserPurge	sta >OrigUserPurge	lda |UserPurge+2	sta >OrigUserPurge+2; Set the new UserPurge vector	lda #XUserPurge	sta |UserPurge+1	lda #>XUserPurge	sta |UserPurge+2; Save the SearchFail vector	lda |SearchFail	sta >OrigSearchFail	lda |SearchFail+2	sta >OrigSearchFail+2; Set the new SearchFail vector	lda #XSearchFail	sta |SearchFail+1	lda #>XSearchFail	sta |SearchFail+2; Save the old purge vector	lda |Purge	sta >OrigPurge	lda |Purge+2	sta >OrigPurge+2; Set the new PurgeVector	lda #XPurge	sta |Purge+1	lda #>XPurge	sta |Purge+2DoNothing	plb	rtlNewMMPatcher	phb	pea $E1E1	plb	plb	php	;added 31-Jan-92 DAL	sei	;added 31-Jan-92 DAL	lda >OrigSearch	sta |Search	lda >OrigSearch+2	sta |Search+2	lda >OrigMMPatcher	sta |MMPatcher	lda >OrigMMPatcher+2	sta |MMPatcher+2	lda >OrigLink	sta |Link	lda >OrigLink+2	sta |Link+2	lda >OrigSearchFail	sta |SearchFail	lda >OrigSearchFail+2	sta |SearchFail+2	lda >OrigUserPurge	sta |UserPurge	lda >OrigUserPurge+2	sta |UserPurge+2	lda >OrigPurge	sta |Purge	lda >OrigPurge+2	sta |Purge+2	lda >OrigBellVector	sta BellVector	lda >OrigBellVector+2	sta BellVector+2*** added 31-Jan-92 DAL -- fix the ToBramSetup vector ($e10094)	lda #$ffb6	;high word of jmp >$ffb6f4	sta |$0094+2	lda #$f45c	;low word of jmp >$ffb6f4	sta |$0094	plp	;restore interrupts*** end 31-Jan-92	plb	rtlOrigSearch	ds.b 4OrigMMPatcher	ds.b 4OrigSearchFail	ds.b 4OrigUserPurge	ds.b 4OrigPurge	ds.b 4	ENDP*****************************************************************MMVersion	PROC** Returns the version number of the patched memory manager.*** Inputs:*	none** Outputs:*	version number** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************	lda #MMVersionNum	sta 7,s	lda #0	;No error	clc	rtl	ENDP*****************************************************************MMReset	PROC** Clears the recent handles and jumps back into rom.*** Inputs:*	none** Outputs:*	none** External Refs:	import ClearRecent** Entry Points:*	none*	longa on	; mode	longi on** Change History** 08 Jan 89	Steven Glass** Also zeroed the FirstOOMPtr so that reset clears the OOM* queue.*****************************************************************RealReset	equ $FF04F1	jsl Link	jsr ClearRecent;; Clear the OOM queue.;	stz |FirstOOMPtr	stz |FirstOOMPtr+2	jml RealReset	ENDP*****************************************************************NewLink	PROC** Jumps back into rom unless one of the new calls* is made (AddToOOMQueue and deleteFromOOMQueue).** For these it does the right link.*** Inputs:*	x-reg** Outputs:*	x-reg, stack and direct page** External Refs:*	none** Entry Points:	ENTRY OrigLink*	longa on	; mode	longi on*****************************************************************RealLink2	equ $FF01A7	cpx #$0C02	beq MakeAdjustment	cpx #$0D02	beq MakeAdjustmentOrigLink	ds.b 4MakeAdjustment	txa	xba	sep #$30	longa off	longi off	and #$FF	; why is this here?	tax	lda #$E1	pha	lda #$04	jml RealLink2	longa on	longi on	ENDP*****************************************************************NewSearch	PROC** This is the entry point into the fast new search routines.* Instead of jumping off to the old routines, this routine* trys to use the fast method first.** The original SearchPatch is also included here.  This* is to patch a bug in SetHandleSize which did not * re-dereference the handle after searching for memory.*** Inputs:*	direct page** Outputs:*	carry*	direct page** External Refs:	import SearchUp	import SearchDownFast	import SearchHandle** Entry Points:	Export XSearch*	longa on	; mode	longi on*****************************************************************	jsl XSearch	php	lda 2,s	cmp #<SHSReturn-1	bne NoExtraFix	lda 3,s	cmp #>SHSReturn	bne NoExtraFix	lda [hndl]	; deref handle again	sta parms	; (it might have moved)	ldy #2	lda [hndl],y	sta parms+2NoExtraFix	plp	rtlXSearch	lda attr	;Check the attributes	bit #attr_addr	;User's address?	beq NotAddr	;Br if not	ora #attr_fixed+attr_bank ;Force these	sta attrNotAddr	bit #attr_fixed	;Movable block?	bne KeepLooking	jmp SearchDownFast	;If not fixed, do top downKeepLooking	bit #attr_handle	;Allocating a handle	bne MustBeHandle	jmp SearchUpMustBehandle	jmp SearchHandle	ENDP*****************************************************************DisposeHandle	PROC** Patch the rom to make sure that handle being disposed is* not the last one allocated.*** Inputs:*	none** Outputs:*	none** External Refs:	import CheckRecent	import VerifyHandle** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************RealDisposeHandle	equ $FF05FF*** 12-Jun-91 DAL -- disposing the very first handle is very bad!;;MemList	equ $E11600	;List of used segments	lda 7,s	cmp >MemList	bne @notFirstHandle	lda 9,s	cmp >MemList+2	bne @notFirstHandle;;;	ldx #$0206	;bad handle error	ldx #0	;no error (21-Nov-91 DAL)	ldy #4	jml $e10184	;ToStrip (4 bytes)@notFirstHandle*** end of 12-Jun-91 DAL	jsl Link;; mensch 11/13/89; Fix BRC#53386 Disposehandle bug. Add the call to verifyHandle...;	jsr VerifyHandle	; added to insure that the passed handle is OK.	jsr CheckRecent	jml RealDisposeHandle	ENDP*****************************************************************DisposeAll	PROC** Patch to ROM to clear all the last allocated handles.** This patch also looks back at the calling routine to * see if its ID is the same as the ID being disposed of.* If it is... shame shame.*** Inputs:*	UserID** Outputs:*	none** External Refs:	import GetIDOfCallingRoutine** Entry Points:	export ClearRecent*	longa on	; mode	longi on*** Change History** 06 Jun 89	Steven Glass** Do not return error if cannot dispose, just return!  This matches* last minute change in ROM too.*****************************************************************RealDisposeAll	equ $FF0610	jsl Link	jsr ClearRecent	jsr GetIDOfCallingRoutine	cmp parms	beq BadID	jml RealDisposeAllBadID	stz error	jml CleanUpClearRecent	stz |LastLowHandle	stz |LastLowHandle+2	stz |LastHighHandle	stz |LastHighHandle+2	rts	ENDP*****************************************************************PurgeHandle	PROC** Patch to ROM to check if the purged handle is the same* as the last allocated handle.*** Inputs:*	handle to purge** Outputs:*	none** External Refs:	import CheckRecent	import VerifyHandle** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************RealPurgeHandle	equ $FF063C	jsl Link;; 11/13/89 Mensch Added call to verify the handle first, just cause I could!;	jsr VerifyHandle	jsr CheckRecent	jml RealPurgeHandle	ENDP*****************************************************************PurgeAll	PROC** Patch to ROM to make clear the recent handles if we* are purging.** This routine also allows a user ID of zero to be passed.** Inputs:*	user id** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************JoinRealMakeID	equ $FF08AEMakeIDReturn	equ $FF064D	jsl Link	jsr ClearRecent	lda parms	sta owner	pea |MakeIDReturn-1	jml JoinRealMakeID	ENDP*****************************************************************SetHandleSize	PROC** Patch to make sure that handles being set to size zero* are removed from the recent list.*** Inputs:*	Size*	Handle** Outputs:*	none** External Refs:	import CheckRecent** Entry Points:*	none*	longa on	; mode	longi on*****************************************************************RealSetHandleSize	equ $FF069C	jsl Link	lda parms+4	ora parms+6	bne NotZero	lda parmhndl	sta hndl	lda parmhndl+2	sta hndl+2	jsr CheckRecentNotZero	jml RealSetHandleSize	ENDP	END